function cmp(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function scalar(n) {
  if (n.t === 'integer') return n.v.toString()
  return JSON.stringify(n.v)
}

function print(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${print(n.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + print(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return scalar(n)
}

export const renderJson = (root) => print(root, 0) + '\n'

export function renderKeys(root) {
  const out = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const k of sortedKeys(n)) {
        const p = path === null ? k : path + '.' + k
        out.push(`${p} table`.replace(/ table$/, ' ' + n.map.get(k).t))
        walk(n.map.get(k), p)
      }
    } else if (n.t === 'array') {
      n.items.forEach((v, i) => {
        const p = `${path}[${i}]`
        out.push(`${p} ${v.t}`)
        walk(v, p)
      })
    }
  }
  walk(root, null)
  return out.map((l) => l + '\n').join('')
}
