const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

const newTable = () => ({ t: 'table', map: new Map(), header: false })

function walkTo(table, names, base) {
  let cur = table
  const path = [...base]
  for (const n of names) {
    path.push(n)
    let child = cur.map.get(n)
    if (!child) {
      child = newTable()
      cur.map.set(n, child)
    }
    if (child.t === 'table') cur = child
    else if (child.t === 'array' && child.aot) cur = child.items[child.items.length - 1]
    else fail(`${path.join('.')} is not a table`)
  }
  return cur
}

function assign(table, names, base, node) {
  const cur = walkTo(table, names.slice(0, -1), base)
  const last = names[names.length - 1]
  if (cur.map.has(last)) fail(`key ${[...base, ...names].join('.')} is defined twice`)
  cur.map.set(last, node)
}

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.c)) this.i++ }
  /** At end of line or at a comment, after skipping whitespace. */
  atEnd() { this.ws(); return this.c === undefined || this.c === '#' || this.c === ';' }

  string() {
    const q = this.c
    this.i++
    let out = ''
    for (;;) {
      const c = this.c
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === q) return out
      if (q === "'" || c !== '\\') { out += c; continue }
      const e = this.c
      if (e === undefined) fail('unterminated string')
      this.i++
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail(`invalid escape \\${String.fromCodePoint(this.s.codePointAt(this.i - 1))}`)
    }
  }

  name() {
    this.ws()
    const c = this.c
    if (c === '"' || c === "'") return this.string()
    const st = this.i
    while (isNameChar(this.c)) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = [this.name()]
    for (;;) {
      this.ws()
      if (this.c !== '.') return names
      this.i++
      names.push(this.name())
    }
  }

  value(base) {
    this.ws()
    const c = this.c
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.string() }
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.c !== undefined && !isWs(this.c) && !',]}'.includes(this.c)) this.i++
    return bare(this.s.slice(st, this.i))
  }

  array(base) {
    this.i++
    const items = []
    for (;;) {
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']') { this.i++; return { t: 'array', items, aot: false } }
      items.push(this.value(base))
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ',') { this.i++; continue }
      if (this.c === ']') { this.i++; return { t: 'array', items, aot: false } }
      fail('unterminated array')
    }
  }

  inline(base) {
    this.i++
    const tbl = newTable()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.c === '}') { this.i++; return tbl }
    for (;;) {
      const names = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value([...base, ...names])
      assign(tbl, names, base, v)
      if (this.atEnd()) fail('unterminated inline table')
      if (this.c === '}') { this.i++; return tbl }
      if (this.c !== ',') fail('unterminated inline table')
      this.i++
      if (this.atEnd()) fail('unterminated inline table')
    }
  }
}

function bare(w) {
  if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
  const D = '\\d+(?:_\\d+)*'
  if (new RegExp(`^[+-]?${D}$`).test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
  const m = new RegExp(`^[+-]?${D}(\\.${D})?([eE][+-]?${D})?$`).exec(w)
  if (m && (m[1] || m[2])) return { t: 'float', v: Number(w.replace(/_/g, '')) }
  return fail(`invalid value ${w}`)
}

function header(L, root) {
  L.i++
  const aot = L.c === '['
  if (aot) L.i++
  const names = L.dotted()
  L.ws()
  if (L.c !== ']') fail('unterminated table header')
  L.i++
  if (aot) {
    if (L.c !== ']') fail('unterminated table header')
    L.i++
  }
  if (!L.atEnd()) fail('trailing text after a table header')
  const path = names.join('.')
  const parent = walkTo(root, names.slice(0, -1), [])
  const last = names[names.length - 1]
  const ex = parent.map.get(last)
  if (aot) {
    const fresh = newTable()
    if (!ex) parent.map.set(last, { t: 'array', items: [fresh], aot: true })
    else if (ex.t === 'array' && ex.aot) ex.items.push(fresh)
    else fail(`${path} is not an array of tables`)
    return { cur: fresh, path: names }
  }
  if (!ex) {
    const t = newTable()
    t.header = true
    parent.map.set(last, t)
    return { cur: t, path: names }
  }
  if (ex.t !== 'table') fail(`${path} is not a table`)
  if (ex.header) fail(`table ${path} is defined twice`)
  ex.header = true
  return { cur: ex, path: names }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root, curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const L = new Line(lines[n])
      L.ws()
      if (L.c === undefined || L.c === '#' || L.c === ';') continue
      if (L.c === '[') {
        const h = header(L, root)
        cur = h.cur
        curPath = h.path
        continue
      }
      const names = L.dotted()
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const v = L.value([...curPath, ...names])
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, names, curPath, v)
    } catch (e) {
      if (e instanceof Fail) { e.confLine = n + 1; throw e }
      throw e
    }
  }
  return root
}
