    return bare(this.s.slice(st, this.i))
  }

  array(base) {
    this.i++
    const items = []
    for (;;) {
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']') { this.i++; return { t: 'array', items, aot: false } }
      items.push(this.value(base))
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ',') { this.i++; continue }
      if (this.c === ']') { this.i++; return { t: 'array', items, aot: false } }
      fail('unterminated array')
    }
  }

  inline(base) {
    this.i++
    const tbl = newTable()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.c === '}') { this.i++; return tbl }
    for (;;) {
      const names = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value([...base, ...names])
      assign(tbl, names, base, v)
      if (this.atEnd()) fail('unterminated inline table')
      if (this.c === '}') { this.i++; return tbl }
      if (this.c !== ',') fail('unterminated inline table')
      this.i++
      if (this.atEnd()) fail('unterminated inline table')
    }
  }
}

function bare(w) {
  if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
  const D = '\\d+(?:_\\d+)*'
  if (new RegExp(`^[+-]?${D}$`).test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
  const m = new RegExp(`^[+-]?${D}(\\.${D})?([eE][+-]?${D})?$`).exec(w)
  if (m && (m[1] || m[2])) return { t: 'float', v: Number(w.replace(/_/g, '')) }
  return fail(`invalid value ${w}`)
}

function header(L, root) {
  L.i++
  const aot = L.c === '['
  if (aot) L.i++
  const names = L.dotted()
  L.ws()
  if (L.c !== ']') fail('unterminated table header')
  L.i++
  if (aot) {
    if (L.c !== ']') fail('unterminated table header')
    L.i++
  }
  if (!L.atEnd()) fail('trailing text after a table header')
  const path = names.join('.')
  const parent = walkTo(root, names.slice(0, -1), [])
  const last = names[names.length - 1]
  const ex = parent.map.get(last)
  if (aot) {
    const fresh = newTable()
    if (!ex) parent.map.set(last, { t: 'array', items: [fresh], aot: true })
    else if (ex.t === 'array' && ex.aot) ex.items.push(fresh)
    else fail(`${path} is not an array of tables`)
    return { cur: fresh, path: names }
  }
  if (!ex) {
    const t = newTable()
    t.header = true
    parent.map.set(last, t)
    return { cur: t, path: names }
  }
  if (ex.t !== 'table') fail(`${path} is not a table`)
  if (ex.header) fail(`table ${path} is defined twice`)
  ex.header = true
  return { cur: ex, path: names }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root, curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const L = new Line(lines[n])
      L.ws()
      if (L.c === undefined || L.c === '#' || L.c === ';') continue
      if (L.c === '[') {
        const h = header(L, root)
        cur = h.cur
        curPath = h.path
        continue
      }
      const names = L.dotted()
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const v = L.value([...curPath, ...names])
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, names, curPath, v)
    } catch (e) {
      if (e instanceof Fail) { e.confLine = n + 1; throw e }
      throw e
    }
  }
  return root
}
